import "../styles/Skills.scss";

const skills = [
  ["HTML", "88%"],
  ["CSS", "84%"],
  ["JavaScript", "72%"],
  ["Python", "88%"],
  ["React JS", "82%"],
  ["Machine Learning", "76%"],
  ["Deep Learning", "68%"],
  ["Scikit-learn", "75%"],
  ["Data Preprocessing", "80%"],
  ["Model Evaluation", "72%"],
];

function Skills() {
  return (
    <section className="skills-section" id="skills">

      {/* Background Decorations */}
      <span className="skills-orb skills-orb-one"></span>
      <span className="skills-orb skills-orb-two"></span>
      <span className="skills-orb skills-orb-three"></span>

      {/* Section Header */}
      <div className="skills-header reveal">

        <span className="section-label">
          MY EXPERTISE
        </span>

        <h2 className="sub-title">
          My <span>Skills</span>
        </h2>

        <p>
          A combination of web development,
          programming and growing Artificial
          Intelligence and Machine Learning skills.
        </p>

      </div>

      {/* Technical Skills Heading */}
      <div className="skills-heading reveal">
        <h3>
          <span className="heading-line"></span>
          Technical Skills
          <span className="heading-line"></span>
        </h3>
      </div>

      {/* Skills Grid */}
      <div className="technical-bars">

        {skills.map(([name, value], index) => {

          const percentage = parseInt(value);

          return (
            <article
              className="skill-card glass-card reveal"
              key={name}
              style={{
                "--skill-index": index,
                "--skill-width": value,
              }}
            >

              {/* Top Reflection */}
              <div className="skill-reflection"></div>

              {/* Shine */}
              <div className="skill-shine"></div>

              {/* Skill Top */}
              <div className="skill-top">

                <div className="skill-icon">
                  <i className="bx bx-code-alt"></i>
                </div>

                <div className="skill-info">

                  <span className="skill-name">
                    {name}
                  </span>

                  <span className="skill-value">
                    {value}
                  </span>

                </div>

              </div>

              {/* Progress */}
              <div className="progress-wrapper">

                <div className="progress-line">
                  <span></span>
                </div>

              </div>

              {/* Bottom Information */}
              <div className="skill-bottom">

                <span>
                  Proficiency
                </span>

                <span>
                  {percentage >= 80
                    ? "Advanced"
                    : percentage >= 70
                    ? "Intermediate"
                    : "Learning"}
                </span>

              </div>

            </article>
          );
        })}

      </div>

    </section>
  );
}

export default Skills;
